DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.hq_product_run_event(uuid,integer,text,text,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'outlet jsonb','v_outlet jsonb'); definition:=replace(definition,'INTO outlet FROM','INTO v_outlet FROM'); definition:=replace(definition,'IF outlet IS NULL','IF v_outlet IS NULL'); definition:=replace(definition,'outlet->','v_outlet->'); EXECUTE definition; END $$;